 unsigned nextClocks(const ControllerDeviceState&d,const ControllerInterruptRuntime&irq)const{if(bound_!=&d||!irq.boundTo(d)||!task_||d.interruptMode2||d.pendingIrqsHigh||irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return 0;if(refresh_)return refresh_->nextClocks(d,irq);if(values_)return values_->nextClocks(d,irq,*valuesDsp_);if(voices_)return voices_->nextClocks(d,irq,*voicesDsp_);if(allSound_)return allSound_->nextClocks(d,irq,*allSoundDsp_);if(sustain_)return sustain_->nextClocks(d,irq,*sustainDsp_);auto cost=task_->nextClocks(d.lastWrite);return cost?cost+(d.pendingIrqs?1u:0u):0;}
 Result advanceBefore(ControllerDeviceState&d,ControllerInterruptRuntime&irq,unsigned available){if(bound_!=&d||!irq.boundTo(d))return {0,false,Block::NotBound};if(!task_)return {0,false,Block::Inactive};if(d.interruptMode2||d.pendingIrqsHigh)return {0,false,Block::UnsupportedMode};if(irq.active()||(d.pendingIrqs&&irq.mask()==ControllerInterruptRuntime::Mask::Enabled))return {0,false,Block::NeedsInterrupt};if(refresh_){auto r=refresh_->advanceBefore(d,irq,available);if(r.returned){refresh_=nullptr;if(!task_->resume(refreshService_))return {r.clocks,false,Block::AwaitRefreshChild};}return {r.clocks,false,r.blocked==ControllerVoiceRefreshRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerVoiceRefreshRuntime::Block::AwaitChild?Block::AwaitRefreshChild:Block::None};}if(values_){auto r=values_->advanceBefore(d,irq,*valuesDsp_,available);if(r.returned){values_=nullptr;valuesDsp_=nullptr;if(!task_->resume(valuesService_))return {r.clocks,false,Block::AwaitService};}return {r.clocks,false,r.blocked==ControllerExpressionValuesRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerExpressionValuesRuntime::Block::DspBusy?Block::DspBusy:Block::None};}if(voices_){auto r=voices_->advanceBefore(d,irq,*voicesDsp_,available);if(r.returned){voices_=nullptr;voicesDsp_=nullptr;if(!task_->resume(Service::ReleaseVoices))return {r.clocks,false,Block::AwaitService};}return {r.clocks,false,r.blocked==ControllerProgramVoicesRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerProgramVoicesRuntime::Block::DspBusy?Block::DspBusy:Block::None};}if(allSound_){auto r=allSound_->advanceBefore(d,irq,*allSoundDsp_,available);if(r.returned){allSound_=nullptr;allSoundDsp_=nullptr;if(!task_->resume(Service::AllSoundOff))return {r.clocks,false,Block::AwaitService};}return {r.clocks,false,r.blocked==ControllerVoiceReleaseAboveRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerVoiceReleaseAboveRuntime::Block::DspBusy?Block::DspBusy:Block::None};}if(sustain_){auto r=sustain_->advanceBefore(d,irq,*sustainDsp_,available);if(r.returned){sustain_=nullptr;sustainDsp_=nullptr;if(!task_->resume(Service::ReleaseSustain))return {r.clocks,false,Block::AwaitService};}return {r.clocks,false,r.blocked==ControllerSustainReleaseRuntime::Block::NeedsInterrupt?Block::NeedsInterrupt:r.blocked==ControllerSustainReleaseRuntime::Block::DspBusy?Block::DspBusy:Block::None};}if(task_->request().service!=Service::None)return {0,false,Block::AwaitService};auto cost=task_->nextClocks(d.lastWrite),arb=d.pendingIrqs?1u:0u;if(!cost||available<cost+arb)return {};if(arb)(void)d.read8(0xfffff2);auto begin=d.cycles;bool stack=task_->stackWrites();auto history=[](uint32_t a){a&=0xffffff;return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;};auto read=[&](uint32_t a,unsigned width,unsigned end){uint32_t value=0;unsigned total=width==4?((a<0x400000)?6:2):((a<0x400000)?3:1),first=width==4?total/2:total;for(unsigned i=0;i<width;++i){auto off=end-total+(i<2?first:total);d.cycles=begin+off;d.lastRead=history(a+i);value=(value<<8)|d.readResource(a+i);}return value;};auto write=[&](uint32_t a,uint32_t v,unsigned width,unsigned end){unsigned total=width==4?((a<0x400000)?6:2):((a<0x400000)?3:1),first=width==4?total/2:total;for(unsigned i=0;i<width;++i){auto off=end-total+(i<2?first:total);d.cycles=begin+off;d.lastWrite=history(a+i);d.writeResource(a+i,uint8_t(v>>(8*(width-i-1))));}};if(task_->advanceBefore(cost,read,write,d.lastWrite)!=cost)return {};d.cycles=begin+cost;d.lastRead=-1;if(stack)d.lastWrite=-1;if(task_->complete()){task_.reset();return {cost+arb,true,Block::None};}return {cost+arb,false,Block::None};}
